insert into public.providers (id, user_id, company_name, contact_name, email, phone, website, description, status) values
  ('33333333-3333-4333-8333-333333333330', 'user-cyp', 'Ciprus Magyarul Élménytúrák', 'Németh Zoltán & Dóra', 'info@ciprusmagyarul.com', '+357 99 123 456', 'https://ciprusmagyarul.com', 'Több mint 8 éve élünk Cipruson. Magyar nyelvű kiscsoportos kirándulásokat, hegyi túrákat és megbízható reptéri transzfereket biztosítunk.', 'approved'),
  ('33333333-3333-4333-8333-333333333331', 'user-mlt', 'Malta & Gozo Magyar Kísérettel', 'Varga Gabriella', 'gabriella@maltamagyarul.hu', '+356 79 456 789', 'https://maltamagyarul.hu', 'Hivatalos máltai engedéllyel rendelkező helyi magyar idegenvezető. Történelmi séták Vallettában, Mdina és Gozo privát élmények.', 'approved'),
  ('33333333-3333-4333-8333-333333333332', 'user-esp', 'Iberia Kalandok – Spanyolországi Magyar Séták', 'Szabó Bence & Carmen', 'hola@iberiakalandok.es', '+34 612 345 678', 'https://iberiakalandok.es', 'Barcelonában, Málagán és Mallorcán szervezünk autentikus magyar nyelvű városi sétákat, szurdoktúrákat és reptéri transzfereket.', 'approved'),
  ('33333333-3333-4333-8333-333333333333', 'user-rom', 'Római Séták & Transzferek', 'Dr. Kovács Márton', 'marton@romaisetak.it', '+39 340 987 6543', 'https://romaisetak.it', 'Rómában élő magyar művészettörténész és idegenvezető. Soron kívüli bejutás a Vatikánba és Colosseumba, Fiumicino transzferek.', 'approved'),
  ('33333333-3333-4333-8333-333333333334', 'user-ist', 'Isztambul Magyar Kísérővel', 'Demir Emese', 'emese@isztambulmagyarul.com', '+90 532 111 2233', 'https://isztambulmagyarul.com', '12 éve Isztambulban élő magyar kísérő: hajózás a Boszporuszon, gasztrotúrák és privát reptéri asszisztencia.', 'approved')
insert into public.programs (id, provider_id, category_id, region_id, title, slug, short_description, description, location, country, departure_location, event_date, start_time, end_time, duration, price, currency, language, included, not_included, max_participants, status, featured) values
  ('44444444-4444-4444-8444-444444444440', '33333333-3333-4333-8333-333333333330', '11111111-1111-4111-8111-111111111110', '22222222-2222-4222-8222-222222222220', 'Troodos-hegység, Kykkos kolostor & Omodos hegyi falu', 'troodos-hegyseg-kykkos-kolostor-omodos-ciprus', 'Magyar nyelvű kisbuszos kirándulás a zöld szívbe: cédruserdők, aranymozaikos kolostor és borkóstoló egy tradicionális hegyi faluban.', 'Fedezd fel Ciprus hűvös, fenyőillatú hegyvidékét magyar vezetéssel! Kirándulásunk során meglátogatjuk az UNESCO világörökségi oltalmú területeket és a Kykkos kolostort.', 'Troodos & Omodos, Ciprus', 'Ciprus', 'Szállodai felvétel: Ayia Napa, Protaras, Larnaca vagy Limassol', '2026-10-15', '08:00', '17:30', 'Egész napos (9 óra)', 65, 'EUR', 'Magyar nyelvű vezetés', array['Szállodai transzfer oda-vissza kisbusszal', 'Magyar nyelvű idegenvezetés', 'Kykkos kolostor belépő', 'Borkóstoló Omodosban'], array['Ebéd hegyi tavernban', 'Egyéni szuvenírek'], 16, 'published', true),
  ('44444444-4444-4444-8444-444444444441', '33333333-3333-4333-8333-333333333330', '11111111-1111-4111-8111-111111111112', '22222222-2222-4222-8222-222222222220', 'Larnaca Reptéri Transzfer (Ayia Napa / Protaras) magyar sofőrrel', 'larnaca-repuloteri-privat-transzfer-magyarul', 'Pontos, megbízható reptéri privát transzfer közvetlenül a szállásodig. Magyar sofőr, nincs stressz, hasznos helyi tippek útközben.', 'Érkezz nyugodtan Ciprusra! A járatod érkezésekor a sofőr névtáblával vár a Larnaca repülőtéren.', 'Larnaca Reptér → Ayia Napa / Protaras / Limassol', 'Ciprus', 'Larnaca Nemzetközi Repülőtér (LCA) érkezési terminál', '2026-10-10', '00:00', '23:59', '45-60 perc', 55, 'EUR', 'Magyar sofőr és asszisztencia', array['Privát transzfer max 4-8 fő részére', 'Névtáblás találkozó', 'Járatkésés díjmentes követése'], array['Borravaló'], 8, 'published', false),
  ('44444444-4444-4444-8444-444444444442', '33333333-3333-4333-8333-333333333331', '11111111-1111-4111-8111-111111111111', '22222222-2222-4222-8222-222222222221', 'Málta esszenciája: Valletta, Mdina és a Három Város magyarul', 'malta-esszenciaja-valletta-mdina-magyar-vezetes', 'A Máltai Lovagrend dicsősége: Felső Barrakka kertek, Szent János társkatedrális és a Csendes Város macskaköves titkai.', 'Ismerd meg Málta 7000 éves történelmét egy lenyűgöző magyar nyelvű sétán! Délelőtt Valletta, délután Mdina.', 'Valletta & Mdina, Málta', 'Málta', 'Valletta, Tritón-kút (City Gate főlépcső)', '2026-10-18', '09:30', '16:00', '6.5 óra', 49, 'EUR', 'Magyar nyelvű idegenvezetés', array['Hivatalos máltai magyar idegenvezető', 'Klímás buszos transzfer Valletta és Mdina között', 'Pasztizzi kóstoló'], array['Katedrális belépőjegy (15 EUR)', 'Ebéd'], 20, 'published', true),
  ('44444444-4444-4444-8444-444444444443', '33333333-3333-4333-8333-333333333331', '11111111-1111-4111-8111-111111111113', '22222222-2222-4222-8222-222222222221', 'Gozo & Comino Kék Lagúna katamarán túra magyar kísérővel', 'gozo-comino-kek-laguna-hajo-tura-magyarul', 'Kristálytiszta türkiz víz, fürdőzés a Kék Lagúnában és Gozo Citadellájának meglátogatása egy felejthetetlen napon.', 'Hajózz velünk a Földközi-tenger legszebb vizű öblébe! Comino szigeténél fürdőzés, majd Gozo Citadella.', 'Comino & Gozo, Málta', 'Málta', 'Sliema Ferries vagy Bugibba kikötő', '2026-10-22', '09:00', '18:00', '9 óra', 58, 'EUR', 'Magyar nyelvű kíséret', array['Hajójegy oda-vissza a katamaránon', 'Fürdési megálló Cominónál', 'Gozói kisbuszos transzfer', 'Magyar csoportkísérő'], array['Ebéd a kikötőben'], 25, 'published', false),
  ('44444444-4444-4444-8444-444444444444', '33333333-3333-4333-8333-333333333332', '11111111-1111-4111-8111-111111111111', '22222222-2222-4222-8222-222222222222', 'Gaudí nyomában: Sagrada Família & Park Güell magyar nyelvű séta', 'gaudi-nyomaban-sagrada-familia-park-guell-magyarul', 'Antoni Gaudí zsenialitása: bejutás a Sagrada Famíliába sorban állás nélkül, Park Güell panoráma és a Casa Batlló titkai.', 'Nem kell órákat sorban állnod! Sagrada Família és Park Güell magyar művészettörténész tolmácsolásában.', 'Barcelona, Katalónia, Spanyolország', 'Spanyolország', 'Barcelona, Sagrada Família metrómegálló kijárat', '2026-10-17', '10:00', '14:30', '4.5 óra', 59, 'EUR', 'Magyar nyelvű vezetés', array['Magyar nyelvű akkreditált idegenvezető', 'Fast track bejutás szervezése', 'Fülhallgatós adóvevő készülék'], array['Belépőjegyek', 'Metrójegy a két helyszín között'], 14, 'published', true),
  ('44444444-4444-4444-8444-444444444445', '33333333-3333-4333-8333-333333333332', '11111111-1111-4111-8111-111111111110', '22222222-2222-4222-8222-222222222222', 'Montserrat szent hegye & Penedès cavakóstoló kisbusszal', 'montserrat-cava-kostolo-barcelona-magyarul', 'Fűrész-fogú sziklahegyek, a Fekete Madonna kolostora, majd látogatás egy 150 éves családi pezsgőpincészetben.', 'Hagyd magad mögött a nagyváros nyüzsgését! Montserrat sziklái, Fekete Madonna és 3 tételes prémium cavakóstoló.', 'Montserrat & Penedès, Katalónia', 'Spanyolország', 'Barcelona, Plaça de Catalunya (Hard Rock Cafe előtt)', '2026-10-24', '08:30', '16:30', '8 óra', 79, 'EUR', 'Magyar nyelvű vezetés', array['Kisbuszos utazás oda-vissza', 'Magyar nyelvű túravezető', 'Kolostor belépő', 'Pincelátogatás és cavakóstoló'], array['Ebéd Montserratban'], 16, 'published', false),
  ('44444444-4444-4444-8444-444444444446', '33333333-3333-4333-8333-333333333332', '11111111-1111-4111-8111-111111111110', '22222222-2222-4222-8222-222222222223', 'Caminito del Rey – A Királyok Ösvénye szurdoktúra magyar kísérővel', 'caminito-del-rey-szurdoktura-malaga-magyarul', 'Spanyolország leghíresebb sziklaösvénye 100 méterrel a Gaitanes-szurdok folyója felett. Biztonságos, garantált belépővel!', 'A világ egyik leglátványosabb kanyonösvénye. Transzfer Málagából, garantált belépővel és magyar kísérővel.', 'El Chorro & Ardales, Málaga tartomány', 'Spanyolország', 'Málaga Maria Zambrano állomás vagy Costa del Sol szállodák', '2026-10-19', '08:00', '15:30', '7.5 óra', 68, 'EUR', 'Magyar kísérő és vezetés', array['Garantált belépőjegy és védősisak', 'Buszos transzfer Málagából', 'Magyar túravezető'], array['Egyéni fogyasztás'], 18, 'published', true),
  ('44444444-4444-4444-8444-444444444447', '33333333-3333-4333-8333-333333333332', '11111111-1111-4111-8111-111111111110', '22222222-2222-4222-8222-222222222224', 'Mallorca rejtett kincsei: Valldemossa, Sóller és Formentor-fok', 'mallorca-rejtett-kincsei-valldemossa-soller-magyarul', 'Chopin zongorája Valldemossában, narancsligeteken átívelő nosztalgiavasút Sóllerben és Mallorca legszebb sziklás kilátója.', 'Kiscsoportos túra a Tramuntana-hegység falvaiban. Sólleri villamosozás és az Es Colomer kilátó.', 'Valldemossa & Sóller, Mallorca', 'Spanyolország', 'Palma de Mallorca belváros vagy Playa de Palma szállodák', '2026-10-21', '09:00', '17:30', '8.5 óra', 72, 'EUR', 'Magyar nyelvű vezetés', array['Kisbuszos utazás Palmából', 'Magyar nyelvű túravezetés', 'Sólleri nosztalgia villamosjegy', 'Mallorcai narancslé és süti'], array['Ebéd Port de Sóllerben'], 16, 'published', false),
  ('44444444-4444-4444-8444-444444444448', '33333333-3333-4333-8333-333333333333', '11111111-1111-4111-8111-111111111111', '22222222-2222-4222-8222-222222222225', 'Ókori Róma & Vatikán kiemelt séta magyar régész-idegenvezetővel', 'okori-roma-vatikan-magyar-regesz-vezetes', 'Colosseum, Forum Romanum, Szent Péter Bazilika és a Sixtus-kápolna titkai soron kívüli bejutással, magyar nyelven.', 'Róma történelme elevenedik meg előtted magyar szakértő idegenvezetéssel. Colosseum, Forum és Vatikán.', 'Róma & Vatikánváros, Olaszország', 'Olaszország', 'Róma, Colosseo metrómegálló kijárat', '2026-10-23', '09:00', '15:30', '6.5 óra', 65, 'EUR', 'Magyar régész-idegenvezető', array['Hivatalos magyar anyanyelvű idegenvezető', 'Soron kívüli bejutás ügyintézése', 'Fülhallgatós adóvevő készülék'], array['Hivatalos belépőjegyek', 'Ebéd'], 15, 'published', true),
  ('44444444-4444-4444-8444-444444444449', '33333333-3333-4333-8333-333333333333', '11111111-1111-4111-8111-111111111112', '22222222-2222-4222-8222-222222222225', 'Róma Fiumicino (FCO) reptéri privát transzfer magyar asszisztenciával', 'roma-fiumicino-repteri-privat-transzfer-magyarul', 'Fix áras, megbízható prémium transzfer a repülőtérről a római belvárosi szállásodig. Nem kell a taxiknál alkudozni!', 'Prémium Mercedes járművel várjuk géped a Fiumicino repülőtéren. Magyar nyelvű telefonos asszisztencia.', 'Fiumicino Repülőtér (FCO) → Róma Belváros', 'Olaszország', 'Róma Fiumicino T3 Nemzetközi Érkezési Csarnok', '2026-10-15', '00:00', '23:59', '40 perc', 60, 'EUR', 'Magyar asszisztencia', array['Privát Mercedes jármű max 4-7 fő', '1 óra várakozási idő', 'Autópályadíj és reptéri engedély', 'Magyar diszpécser'], array['Éjszakai felár (22:00-06:00 között)'], 7, 'published', false),
  ('44444444-4444-4444-8444-44444444444a', '33333333-3333-4333-8333-333333333334', '11111111-1111-4111-8111-111111111111', '22222222-2222-4222-8222-222222222226', 'Isztambul két kontinensen: Boszporusz hajózás & Hagia Sophia magyarul', 'isztambul-ket-kontinensen-boszporusz-hagia-sophia-magyarul', 'Hagia Sophia, Kék Mecset, Elsüllyedt Palota, majd privát hajózás a Boszporuszon Európa és Ázsia partjai mentén.', 'Sultanahmet csodái és privát hajózás a Boszporuszon magyar kísérővel Európa és Ázsia partjai között.', 'Sultanahmet & Boszporusz, Isztambul', 'Törökország', 'Isztambul, Sultanahmet tér (Német kút mellett)', '2026-10-25', '09:30', '16:30', '7 óra', 55, 'EUR', 'Magyar nyelvű vezetés', array['Magyar nyelvű hivatalos helyi idegenvezetés', '2 órás hajózás a Boszporuszon kishajóval', 'Török tea és perec a hajón'], array['Múzeumi belépőjegyek', 'Ebéd'], 18, 'published', true),
  ('44444444-4444-4444-8444-44444444444b', '33333333-3333-4333-8333-333333333334', '11111111-1111-4111-8111-111111111114', '22222222-2222-4222-8222-222222222226', 'Ázsiai Ízutazás: Kadiköy gasztrotúra & Fűszerbazár magyarul', 'azsiai-izutazas-kadikoy-gasztrotura-isztambul-magyarul', 'Kompátkelés Ázsiába, utcai ételek, valódi török kávéfőzés parázson, baklava mesterek és fűszer kavalkád.', 'Sárga komppal áthajózunk az ázsiai Kadiköybe. 6 féle autentikus utcai ételkóstoló és valódi török kávé parázson.', 'Kadiköy & Eminönü, Isztambul', 'Törökország', 'Eminönü kompkikötő bejárat', '2026-11-01', '11:00', '16:00', '5 óra', 45, 'EUR', 'Magyar nyelvű kíséret', array['Magyar gasztro-idegenvezetés', '6 féle autentikus utcai ételkóstoló', 'Török kávé parázson', 'Kompjegy oda-vissza'], array['Nagybevásárlás a bazárban'], 12, 'published', false)
